function PVPArenaHonorListDialog:__init()
    self.yearIndex = 1
    self.expandIndex = 0
end

function PVPArenaHonorListDialog:__delete()
end

function PVPArenaHonorListDialog:Awake()
    --- 第一届不应该进入 荣誉列表
    self.__EventRequestHistorySeasonSuccess = Events.AddListener(Constants.EventNames.PVPArenaRequestHistorySeasonSuccess, Bind(self, self.EventRequestHistorySeasonSuccess))
    UIEventProxy.Create(self.BtnCloseArea.gameObject).onPointerClick = Bind(self, self.OnClickBtnCloseAreaAction)
    UIEventProxy.Create(self.BtnArrowLArea.gameObject).onPointerClick = Bind(self, self.OnClickArrowAreaLAction)
    UIEventProxy.Create(self.BtnArrowRArea.gameObject).onPointerClick = Bind(self, self.OnClickArrowAreaRAction)
end

function PVPArenaHonorListDialog:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        PVPArenaUtils.RefreshCommonUITitleNode(self.CommonUITitleNode.gameObject, localize("荣誉榜单"))
        pvpArenaComponent:RequestHistorySeason()
    end))
    return coWait
end

function PVPArenaHonorListDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()

        if self.__EventRequestHistorySeasonSuccess then
            Events.RemoveListener(Constants.EventNames.PVPArenaRequestHistorySeasonSuccess, self.__EventRequestHistorySeasonSuccess)
            self.__EventRequestHistorySeasonSuccess = nil
        end

        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

function PVPArenaHonorListDialog:InitData(data)
    local history              = checkTable(data.history)
    local year2HistoryDataList = {}
    local year2count           = {}
    local years                = {}
    for i, historyData in ipairs(history) do
        local year = checkNumber(historyData.year)
        year2HistoryDataList[year] = year2HistoryDataList[year] or {}
        if year2count[year] == nil then
            year2count[year] = 1
            table.insert(years, year)
        else
            year2count[year] = year2count[year] + 1
        end
        historyData.seasonId = checkNumber(historyData.seasonId)
        table.insert(year2HistoryDataList[year], historyData)
    end

    for year, historyDataList in pairs(year2HistoryDataList) do
        local historyDataCount = year2count[year]
        for i = historyDataCount+1, MinItemCount do
            table.insert(historyDataList, {seasonId = EmptyNodeSeasonId})
        end
        table.sort(historyDataList, function(a, b)
            return a.seasonId > b.seasonId
        end)
    end

    table.sort(years, function(a, b)
        return a > b
    end)

    local count       = table.count(years)
    self.maxYearIndex = count < 1 and 1 or count
    self.yearIndex    = self.maxYearIndex
    self.years        = years
    self.year2HistoryDataList = year2HistoryDataList
end

