function PVPArenaHonorListDialog:EventRequestHistorySeasonSuccess(data)
    print(table.toString(data))
    self:InitData(data)
    self:RefreshUI()
end

function PVPArenaHonorListDialog:RefreshUI()
    self:RefreshButtonArrow()
    self:RefreshButtonYearText()
    self:RefreshLoopHonorListView()
end

---RefreshButtonArrow
---刷新箭头按钮
function PVPArenaHonorListDialog:RefreshButtonArrow()
    local years     = self.years
    local yearIndex = self.yearIndex

    local GetImageName = function(index)
        return years[index] and "pvp_history_arrow_01" or "pvp_history_arrow_02"
    end
    self.BtnArrowL:LoadSprite(string.format(BasePath, GetImageName(yearIndex - 1)))
    self.BtnArrowR:LoadSprite(string.format(BasePath, GetImageName(yearIndex + 1)))
end

function PVPArenaHonorListDialog:RefreshButtonYearText()
    self.YearText.text = self.years[self.yearIndex]
end

function PVPArenaHonorListDialog:RefreshLoopHonorListView()
    local year = self.years[self.yearIndex]
    if year == nil then return end

    local historyDataList = self.year2HistoryDataList[year]
    local ListView = self.LoopHonorListView
    if not ListView.IsListViewInit then
        ListView:InitListView(#historyDataList, Bind(self, self.OnGetItemByIndex))
    else
        GameUtils.ReloadData(ListView, #historyDataList)
    end
end

function PVPArenaHonorListDialog:OnGetItemByIndex(listView, idx)
    if idx < 0 then
        return nil
    end
    local cell = listView:NewListViewItem(NodeName)
    local node = GetLuaBehaviour(cell.gameObject, NodePath)
    if not cell.IsInitHandlerCalled then
        cell.IsInitHandlerCalled = true
        node:Init()
        local Env = node.Env
        Env:SetCallback(Bind(self, self.OnClickCellAction))
    end
    if not KTool.IsNull(node) then
        local index           = idx + 1
        local year            = self.years[self.yearIndex]
        local historyDataList = self.year2HistoryDataList[year]
        local historyData     = historyDataList[index]

        local isExpand = index == self.expandIndex
        ---@type PVPArenaHonorListItem
        local Env = node.Env
        Env:RefreshUI(historyData, index, isExpand)
        if isExpand then
            listView:OnItemSizeChanged(idx)
        end
    end
    return cell
end

