function PVPArenaHonorListDialog:OnClickBtnCloseAreaAction()
    UIModule.BackDialog()
end

function PVPArenaHonorListDialog:OnClickArrowAreaLAction()
    if self.yearIndex <= 1 then return end
    self.yearIndex = self.yearIndex - 1
    self:RefreshUI()
end

function PVPArenaHonorListDialog:OnClickArrowAreaRAction()
    if self.yearIndex >= self.maxYearIndex then return end
    self.yearIndex = self.yearIndex + 1
    self:RefreshUI()
end

function PVPArenaHonorListDialog:OnClickCellAction(cellEnv, index)
    if self.expandIndex == index then
        cellEnv:SetIsExpand(false)
        self.expandIndex = 0
        self.LoopHonorListView:OnItemSizeChanged(index - 1)
        return
    end

    local oldExpandIndex = self.expandIndex
    if oldExpandIndex > 0 then
        local item = self.LoopHonorListView:GetShownItemByItemIndex(oldExpandIndex - 1)
        local Env = CfUtils.GetLuaScr(item.gameObject, NodePath)
        Env:SetIsExpand(false)
        self.LoopHonorListView:OnItemSizeChanged(oldExpandIndex - 1)
    end

    local idx = index - 1
    cellEnv:SetIsExpand(true)
    self.expandIndex = index
    self.LoopHonorListView:OnItemSizeChanged(idx)

end

---------------------------------------------------
--- click handler end --
